cd /user/user1/harbor-runs/e3abc148a772/workspace
echo "=== run.sh ==="; cat -n run.sh
echo "=== staleness theta/proximal trend (extract v_theta, staleness_theta_avg, staleness_proximal_avg per step) ==="
python3 - <<'PY'
import re
p="run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log"
cur=0
vals={}
order=[]
for line in open(p,encoding='utf8',errors='replace'):
    m=re.search(r"Train step (\d+)/87 done",line)
    if m:
        cur=int(m.group(1))
        if cur not in vals:
            vals[cur]={}
            order.append(cur)
    for key,pat in [("v_theta",r"v_theta\s*│\s*([0-9.eE+\-]+)"),
                    ("stal_th_avg",r"sample_staleness_theta_avg\s*\S{0,3}\s*([0-9.eE+\-]+)"),
                    ("stal_th_max",r"sample_staleness_theta_max\s*\S{0,3}\s*([0-9.eE+\-]+)"),
                    ("stal_pr_avg",r"sample_staleness_proximal_avg\s*\S{0,3}\s*([0-9.eE+\-]+)"),
                    ("v_prox",r"v_proximal\s*│\s*([0-9.eE+\-]+)")]:
        m=re.search(pat,line)
        if m and cur: vals[cur][key]=float(m.group(1))
# print at selected steps
show=[1,10,20,29,30,40,46,58,64,66,70,79,87]
for s in show:
    if s in vals:
        print(s, vals[s])
PY

