import re
p="run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log"
cur=0; d={}
for line in open(p,encoding='utf8',errors='replace'):
    m=re.search(r"Train step (\d+)/87 done",line)
    if m: cur=int(m.group(1)); d.setdefault(cur,{})
    for key,pat in [("grad_norm",r"grad_norm\s*\S{0,3}\s*([0-9.eE+\-]+)"),
                    ("n_masked",r"n_masked_tokens\s*\S{0,3}\s*([0-9.eE+\-]+)"),
                    ("rs_filtered",r"rs_filtered_fraction\s*\S{0,3}\s*([0-9.eE+\-]+)"),
                    ("iw_avg",r"importance_weight/avg\s*\S{0,3}\s*([0-9.eE+\-]+)")]:
        m=re.search(pat,line)
        if m and cur and key not in d[cur]: d[cur][key]=float(m.group(1))
for s in [1,29,58,66,87]:
    print(s, {k:(round(v,4) if v is not None else None) for k,v in d.get(s,{}).items()})
